import{z as l,x as B,o as t,c as d,q as A,j as o,D as e,d as E,s as n,S as s,b as r}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"Gibbard–Satterthwaite","description":"","frontmatter":{"title":"Gibbard–Satterthwaite","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/gibbard-satterthwaite.md","filePath":"econ/gibbard-satterthwaite.md","lastUpdated":1791413859000}'),p={name:"econ/gibbard-satterthwaite.md"};function h(b,a,c,m,D,C){const i=B("Mermaid");return t(),d("div",null,[a[2]||(a[2]=A('<h1 id="gibbard–satterthwaite" tabindex="-1">Gibbard–Satterthwaite <a class="header-anchor" href="#gibbard–satterthwaite" aria-label="Permalink to &quot;Gibbard–Satterthwaite&quot;">​</a></h1><div class="epigraph"><p>若备选方案不少于三个、偏好定义域不受限，则非独裁的社会选择无法在占优策略下实施。</p><footer>—— Gibbard, Manipulation of Voting Schemes, Econometrica, 1973；Satterthwaite, Strategy-proofness and Arrow’s Conditions, JET, 1975</footer></div><p><a href="/econ/myerson-virtual-value">上一课</a>在拟线性货币里把最优拍卖写成虚拟价值铁钟；再往前，VCG 还能占优策略实施有效配置。缺口是把货币拿掉：只对方案排序投票。此时占优策略 IC 几乎只留下独裁。本课钉这条不可能，作为信息课序在「没有转移」一端的收束，不重写拍卖公式，也不把单峰定义域的中位投票写成解。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有限方案集 \\(A\\)，\\(|A|\\ge 3\\)。每人报一个严格排序，社会选择函数 \\(f\\) 吐出一个方案。策略证明：报真排序是占优策略。<span class="marginnote">「策略证明」翻译成大白话：说真话是每个人的最优策略，而且不管别人怎么报都最优——像考试没有抄近道的动机。这是激励相容里最强的标准（占优策略级）：不需要猜别人投什么，真话单方面就是最好选择。</span>到上（onto）或帕累托：每个方案都可能被选，或一致同意的方案必被选。Gibbard–Satterthwaite：满足这些的 \\(f\\) 必是独裁——存在 \\(i\\)，使 \\(f\\) 永远等于 \\(i\\) 的最爱。</p><p>与 Arrow 的对照：Arrow 在社会排序上要帕累托、无关方案独立性、非独裁，结论是不可能。GS 在社会选择（只吐一个点）上要策略证明，结论同样是独裁。两条定理可互推（在适当技术条件下）：策略证明大约相当于 IIA 加帕累托。显示原理在这里已经用过：只需看直接报排序的规则。</p><h3 id="不可能的是占优策略-不是贝叶斯" tabindex="-1">不可能的是占优策略，不是贝叶斯 <a class="header-anchor" href="#不可能的是占优策略-不是贝叶斯" aria-label="Permalink to &quot;不可能的是占优策略，不是贝叶斯&quot;">​</a></h3><p>允许先验、只要求贝叶斯 IC，能实施的更多，但依赖共同先验，投票场合往往没有。Myerson 拍卖走贝叶斯层，并且有货币把偏好收成数字；GS 两者都没有。</p><p><span class="marginnote">独裁不是「有人说了算就效率低」。独裁策略证明、也帕累托（对独裁者）。定理说的是：要想非独裁，就必须放弃占优策略或限制定义域。VCG 逃出去，是因为拟线性加转移把定义域收成另一类偏好。</span></p><p>\\(|A|=2\\) 时多数规则策略证明，定理从三个方案起算。 无差异、随机化（随机独裁、随机中位）可以放松，本课只钉确定性 SCF。 操纵就是谎报排序使 \\(f\\) 对自己更好；定理说非独裁规则总有人能这样。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：有限 \\(A\\)，普遍定义域（所有严格排序都可报），确定性 \\(f\\)。结论：策略证明 + 到上 \\(\\Rightarrow\\) 独裁。证明策略不在此重写；课堂上认两点：VCG 用的货币不在工具箱里；<a href="/econ/matching-strategy-proof">DA</a> 能单边策略证明，是因为匹配的结果空间与定义域都不是「任意 \\(A\\) 上的任意排序」。</p>',12)),(t(),o(s,null,{default:e(()=>[n(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20MON%5B%22%E6%8B%9F%E7%BA%BF%E6%80%A7%20%2B%20%E8%B4%A7%E5%B8%81%EF%BC%9AVCG%20%2F%20Myerson%22%5D%20--%3E%20DROP%5B%22%E6%8B%BF%E6%8E%89%E8%BD%AC%E7%A7%BB%22%5D%0A%20%20UNIV%5B%22%7CA%7C%E2%89%A53%EF%BC%8C%E6%99%AE%E9%81%8D%E5%AE%9A%E4%B9%89%E5%9F%9F%22%5D%20--%3E%20GS%5B%22%E7%AD%96%E7%95%A5%E8%AF%81%E6%98%8E%20%E2%87%92%20%E7%8B%AC%E8%A3%81%22%5D%0A%20%20DOM%5B%22%E9%99%90%E5%88%B6%E5%AE%9A%E4%B9%89%E5%9F%9F%EF%BC%9A%E5%8D%95%E5%B3%B0%22%5D%20--%3E%20MED%5B%22%E4%B8%AD%E4%BD%8D%E6%8A%95%E7%A5%A8%E5%8F%AF%E7%AD%96%E7%95%A5%E8%AF%81%E6%98%8E%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"没有转移时，无法用「付你造成的外部性」对齐私人目标与社会目标。占优策略要求：无论别人报什么，单个人不能靠谎报把结果扳向自己更爱的方案。三个以上方案提供足够空间让非独裁规则在某对偏好轮廓上被扳动——这是操纵的几何。独裁把空间缩成一个人的最爱，谎报无益。",-1)),(t(),o(s,null,{default:e(()=>[n(i,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRUE%5B%22%E6%8A%95%E7%A5%A8%E4%BA%BA%E7%9C%9F%E5%AE%9E%E6%8E%92%E5%BA%8F%3A%20A%20%3E%20B%20%3E%20C%22%5D%20--%3E%20RULE%5B%22%E9%9D%9E%E7%8B%AC%E8%A3%81%E8%A7%84%E5%88%99%E5%9C%A8%E6%9F%90%E8%BD%AE%E5%BB%93%E4%B8%8B%E9%80%89%E5%87%BA%20B%22%5D%0A%20%20RULE%20--%3E%20GAP%5B%22%E7%BB%93%E6%9E%9C%20B%20%E5%B7%AE%E4%BA%8E%E4%BB%96%E7%9A%84%E6%9C%80%E7%88%B1%20A%22%5D%0A%20%20GAP%20--%3E%20LIE%5B%22%E8%B0%8E%E6%8A%A5%3A%20%E6%8A%AC%E9%AB%98%20A%20%E7%9A%84%E5%AF%B9%E6%89%8B%E4%BB%A5%E6%90%85%E5%B1%80%22%5D%0A%20%20LIE%20--%3E%20OUT%5B%22%E7%BB%93%E6%9E%9C%E8%A2%AB%E6%89%B3%E5%90%91%20A%3A%20%E6%93%8D%E7%BA%B5%E6%88%90%E5%8A%9F%22%5D%0A%20%20OUT%20--%3E%20GS%5B%22%E9%9D%9E%E7%8B%AC%E8%A3%81%E8%A7%84%E5%88%99%E6%80%BB%E5%AD%98%E5%9C%A8%E6%AD%A4%E8%BD%AE%E5%BB%93%20%E2%86%92%20%E5%8F%AA%E5%89%A9%E7%8B%AC%E8%A3%81%E6%97%A0%E7%A9%BA%E9%97%A8%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<p><span class="marginnote">操纵的数字直觉：两个方案时，多数规则下谎报只会帮对面——没有空门。方案到三个，排名给出「用第二爱换掉第三爱」的空间：故意捧高某个方案，能让本会赢的第三爱被你的第二爱挤掉。三个位置就是操纵的最小舞台，定理说任何非独裁规则都躲不开这个舞台。</span></p><p>匹配 DA 不违反 GS：方案集是匹配，偏好被限制成「只关心自己的对象」，不是 \\(A\\) 上的任意排序；而且 DA 只对一边策略证明。拍卖 VCG 不违反 GS：偏好是拟线性的，结果含货币。GS 钉的是无限制序数偏好、无货币、确定性选择。三个方案已经够造出「循环」：非独裁规则必须在某对轮廓上让某人的第二选择压过第一，于是他有谎报动机。这是操纵的最小几何，与 Arrow 的 IIA 失败同源。</p><p>\\(|A|=2\\) 时多数规则策略证明，定理从三个方案起算。 随机独裁、单峰中位是后继放松，不是对本定理的否定。 显示原理已经用过：只需看直接报排序的规则，弯程序救不了。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>单峰偏好（Black、Moulin）：中位投票策略证明，定义域限制救了实施。可分物品、拟线性，VCG 再救一次。随机社会选择、近似策略证明、大规模匿名，都是后继放松。<span class="marginnote">初学者容易把 GS 读成「民主投票注定被操纵」。定理只说：占优策略 + 普遍定义域 + 无货币这个组合下只剩独裁。现实制度靠三样东西绕开它——限制定义域（如单峰）、议程设计、或引入货币与市场。这是一份设计约束清单，不是对投票的否定。</span>不要把 GS 写成「投票无用」：它说占优策略 + 普遍定义域太强；制度靠的是定义域、议程、货币或重复博弈。</p><p>后课进入<a href="/econ/potential-outcomes">潜在结果</a>，不再把因果系数当成某个策略证明的社会选择。信息课序在此收束：有货币则包络与虚值，无货币则 GS。宏观核算更后才出现。</p><h3 id="显示原理没有取消不可能" tabindex="-1">显示原理没有取消不可能 <a class="header-anchor" href="#显示原理没有取消不可能" aria-label="Permalink to &quot;显示原理没有取消不可能&quot;">​</a></h3><p>任何间接投票规则的占优策略均衡结果，都能收成直接策略证明的 \\(f\\)。因此「设计更弯的投票程序」救不了：若直接的 \\(f\\) 只能是独裁，间接的也只能实施独裁结果。这与 Myerson–Satterthwaite、竞争筛选无均衡同一逻辑——可行 IC 集太小。</p><p><span class="marginnote">Gibbard 1973 用博弈形式；Satterthwaite 1975 连到 Arrow。课堂上记：三个方案、普遍定义域、占优策略、非随机 ⇒ 独裁。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无转移、普遍定义域、\\(|A|\\ge 3\\)：策略证明的 SCF 必独裁。</li><li>VCG / Myerson 靠拟线性货币逃出；DA 靠受限偏好与单边。</li><li>显示原理表明弯程序救不了。</li><li>要非独裁，必须限定义域、加随机、加货币或放弃占优策略。</li><li>出处：Gibbard, <em>Econometrica</em> 1973；Satterthwaite, <em>JET</em> 1975。</li></ul>',11))])}const u=l(p,[["render",h]]);export{S as __pageData,u as default};
